            case BirByRefLoad node: WriteBirByRefLoad(ref writer, node, depth); break;
            case BirByRefStore node: WriteBirByRefStore(ref writer, node, depth); break;
            case BirReturnExpression node: WriteBirReturnExpression(ref writer, node, depth); break;
            case BirUnsupportedExpression node: WriteBirUnsupportedExpression(ref writer, node, depth); break;
            case BirConstant node: WriteBirConstant(ref writer, node, depth); break;
            case BirObjectEquals node: WriteBirObjectEquals(ref writer, node, depth); break;
            case BirExpressionStatement node: WriteBirExpressionStatement(ref writer, node, depth); break;
            case BirThrowExpression node: WriteBirThrowExpression(ref writer, node, depth); break;
            case BirUnaryOperation node: WriteBirUnaryOperation(ref writer, node, depth); break;
            case BirConditional node: WriteBirConditional(ref writer, node, depth); break;
            case BirNullableHasValue node: WriteBirNullableHasValue(ref writer, node, depth); break;
            case BirNullableValue node: WriteBirNullableValue(ref writer, node, depth); break;
            case BirEnumValue node: WriteBirEnumValue(ref writer, node, depth); break;
            case BirEnumValues node: WriteBirEnumValues(ref writer, node, depth); break;
            case BirCompanionValue node: WriteBirCompanionValue(ref writer, node, depth); break;
            case BirClassReference node: WriteBirClassReference(ref writer, node, depth); break;
            case BirNullableNull node: WriteBirNullableNull(ref writer, node, depth); break;
            case BirDefaultParameter node: WriteBirDefaultParameter(ref writer, node, depth); break;
            case BirDefaultReceiver node: WriteBirDefaultReceiver(ref writer, node, depth); break;
            case BirBindingReference node: WriteBirBindingReference(ref writer, node, depth); break;
            case BirLocalFunctionReference node: WriteBirLocalFunctionReference(ref writer, node, depth); break;
            case BirValueBlock node: WriteBirValueBlock(ref writer, node, depth); break;
            case BirNew node: WriteBirNew(ref writer, node, depth); break;
            case BirThrow node: WriteBirThrow(ref writer, node, depth); break;
            case BirIf node: WriteBirIf(ref writer, node, depth); break;
            case BirReturn node: WriteBirReturn(ref writer, node, depth); break;
            case BirSetLocal node: WriteBirSetLocal(ref writer, node, depth); break;
            case BirSetField node: WriteBirSetField(ref writer, node, depth); break;
            case BirBlock node: WriteBirBlock(ref writer, node, depth); break;
            case BirBranchIf node: WriteBirBranchIf(ref writer, node, depth); break;
            case BirTry node: WriteBirTry(ref writer, node, depth); break;
            case BirForArray node: WriteBirForArray(ref writer, node, depth); break;
            case BirForIn node: WriteBirForIn(ref writer, node, depth); break;
            case BirVariable node: WriteBirVariable(ref writer, node, depth); break;
            case BirLocal node: WriteBirLocal(ref writer, node, depth); break;
            case BirThis node: WriteBirThis(ref writer, node, depth); break;
            case BirSourcePoint node: WriteBirSourcePoint(ref writer, node, depth); break;
            case BirBreak node: WriteBirBreak(ref writer, node, depth); break;
            case BirContinue node: WriteBirContinue(ref writer, node, depth); break;
            case BirGoto node: WriteBirGoto(ref writer, node, depth); break;
            case BirLabel node: WriteBirLabel(ref writer, node, depth); break;
            case BirWhile node: WriteBirWhile(ref writer, node, depth); break;
            case BirFor node: WriteBirFor(ref writer, node, depth); break;
            case BirForRange node: WriteBirForRange(ref writer, node, depth); break;
            case BirConvert node: WriteBirConvert(ref writer, node, depth); break;
            case BirNewList node: WriteBirNewList(ref writer, node, depth); break;
            case BirNewClr node: WriteBirNewClr(ref writer, node, depth); break;
            case BirConstrainedCall node: WriteBirConstrainedCall(ref writer, node, depth); break;
            case BirGenericStatic node: WriteBirGenericStatic(ref writer, node, depth); break;
            case BirGenericInstance node: WriteBirGenericInstance(ref writer, node, depth); break;
            case BirClrStaticField node: WriteBirClrStaticField(ref writer, node, depth); break;
            case BirEventAccessorBody node: WriteBirEventAccessorBody(ref writer, node, depth); break;
            case BirEventAdd node: WriteBirEventAdd(ref writer, node, depth); break;
            case BirEventRemove node: WriteBirEventRemove(ref writer, node, depth); break;
            case BirNativeInstance node: WriteBirNativeInstance(ref writer, node, depth); break;
            case BirNativeStatic node: WriteBirNativeStatic(ref writer, node, depth); break;
            case BirPropertyGet node: WriteBirPropertyGet(ref writer, node, depth); break;
            case BirPropertySet node: WriteBirPropertySet(ref writer, node, depth); break;
            case BirDelegateInvoke node: WriteBirDelegateInvoke(ref writer, node, depth); break;
            case BirEnumBits node: WriteBirEnumBits(ref writer, node, depth); break;
            case BirForEach node: WriteBirForEach(ref writer, node, depth); break;
            case BirBoundClrDelegate node: WriteBirBoundClrDelegate(ref writer, node, depth); break;
            case BirClrStaticDelegate node: WriteBirClrStaticDelegate(ref writer, node, depth); break;
            case BirRepeat node: WriteBirRepeat(ref writer, node, depth); break;
            default: throw new FormatException();
        }
    }

    internal static IBirExpression ReadBirExpression(ref MessagePackReader reader) => ReadNode(ref reader) as IBirExpression ?? throw new FormatException();
    internal static void WriteBirExpression(ref MessagePackWriter writer, IBirExpression value, int depth) => WriteNode(ref writer, (BirGraphNode)value, depth);

    internal static IBirStatement ReadBirStatement(ref MessagePackReader reader) => ReadNode(ref reader) as IBirStatement ?? throw new FormatException();
    internal static void WriteBirStatement(ref MessagePackWriter writer, IBirStatement value, int depth) => WriteNode(ref writer, (BirGraphNode)value, depth);

    internal static IBirAttributeValue ReadBirAttributeValue(ref MessagePackReader reader) =>
        HasProperty(reader, "k") ? ReadBirExpression(ref reader) :
        HasProperty(reader, "bytes") ? ReadBirOpaqueBytes(ref reader) : ReadBirAttributeLiteral(ref reader);
    internal static void WriteBirAttributeValue(ref MessagePackWriter writer, IBirAttributeValue value, int depth)
    {
        if (value is BirOpaqueBytes bytes) WriteBirOpaqueBytes(ref writer, bytes, depth);
        else if (value is BirAttributeLiteral literal) WriteBirAttributeLiteral(ref writer, literal, depth);
        else WriteBirExpression(ref writer, (IBirExpression)value, depth);
    }

    internal static IBirTypeDeclaration ReadBirTypeDeclaration(ref MessagePackReader reader) => Discriminator(reader, "kind") switch
    {
        "class" => ReadBirClassDefinition(ref reader),
        "struct" => ReadBirClassDefinition(ref reader),
        "delegate" => ReadBirClassDefinition(ref reader),
        "interface" => ReadBirInterfaceDefinition(ref reader),
        "enum" => ReadBirEnumDefinition(ref reader),
        _ => throw new FormatException(),
    };
    internal static void WriteBirTypeDeclaration(ref MessagePackWriter writer, IBirTypeDeclaration value, int depth)
    {
        switch (value)
        {
            case BirClassDefinition node: WriteBirClassDefinition(ref writer, node, depth); break;
            case BirInterfaceDefinition node: WriteBirInterfaceDefinition(ref writer, node, depth); break;
            case BirEnumDefinition node: WriteBirEnumDefinition(ref writer, node, depth); break;
            default: throw new FormatException();
        }
    }

    private delegate T Reader<T>(ref MessagePackReader reader);
    private static T[] ReadArray<T>(ref MessagePackReader reader, Reader<T> read)
    {
        Enter(ref reader);
        var count = reader.ReadArrayHeader();
        if (count > reader.Sequence.Length - reader.Consumed) throw new FormatException();
        var result = new T[count];
        for (var index = 0; index < count; index++) result[index] = read(ref reader);
        reader.Depth--;
        return result;
    }
    private static int ReadMap(ref MessagePackReader reader)
    {
        Enter(ref reader);
        var count = reader.ReadMapHeader();
        if (count > (reader.Sequence.Length - reader.Consumed) / 2) throw new FormatException();
        return count;
    }
    private static void Enter(ref MessagePackReader reader) { CheckDepth(reader.Depth); reader.Depth++; }
    private static void CheckDepth(int depth) { if (depth >= BirJson.MaxDepth) throw new FormatException(); }
    private static void Seen(ref ulong seen, ulong bit) { if ((seen & bit) != 0) throw new FormatException(); seen |= bit; }
    private static string Discriminator(MessagePackReader reader, string key)
    {
        var count = ReadMap(ref reader);
        for (var index = 0; index < count; index++)
        {
            if (IrMessagePack.ReadString(ref reader) == key) return IrMessagePack.ReadString(ref reader);
            reader.Skip();
        }
        throw new FormatException();
    }
    private static bool HasProperty(MessagePackReader reader, string key)
    {
        var count = ReadMap(ref reader);
        for (var index = 0; index < count; index++)
        {
            if (IrMessagePack.ReadString(ref reader) == key) return true;
            reader.Skip();
        }
        return false;
    }
}
